<?php require dirname(__DIR__).'/inc/page_helpers.php';moderator_required();
if(page_post()){check_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');$note=trim((string)($_POST['note']??''));$status=['suspend'=>'suspended','ban'=>'banned','restore'=>'active'][$action]??null;$q=$db->prepare('SELECT role FROM users WHERE id=?');$q->execute([$id]);$target=$q->fetch();if($status&&$target&&$id!==(int)$currentUser['id']&&($currentUser['role']==='admin'||$target['role']==='user')){$db->prepare('UPDATE users SET account_status=? WHERE id=?')->execute([$status,$id]);$db->prepare('INSERT INTO moderation_actions(moderator_id,target_user_id,action,note) VALUES(?,?,?,?)')->execute([$currentUser['id'],$id,$action,$note]);notice('Account status updated.');}else notice('You cannot moderate this account.','error');go('/Admin/Users.php');}
$users=$db->query('SELECT id,username,role,account_status,created_at FROM users ORDER BY id DESC LIMIT 200')->fetchAll();page_start('Manage Users');?><section class="Panel"><h1>Manage Users</h1><table class="Grid"><tr><th>User</th><th>Role</th><th>Status</th><th>Action</th></tr><?php foreach($users as $u):?><tr><td><a href="/User.php?id=<?=(int)$u['id']?>"><?=e($u['username'])?></a></td><td><?=e($u['role'])?></td><td><?=e($u['account_status'])?></td><td><?php if((int)$u['id']!==(int)$currentUser['id']&&($currentUser['role']==='admin'||$u['role']==='user')):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><input name="note" placeholder="Reason (optional)"><button name="action" value="suspend">Suspend</button><button name="action" value="ban">Ban</button><button name="action" value="restore">Restore</button></form><?php endif;?></td></tr><?php endforeach;?></table></section><?php page_end();?>